import java.util.*:

class Solution {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        String items = sc.nextLine().trim();
        String prices = sc.nextLine().trim();

        ArrayList<String> l1 = new ArrayList<>();       // item names
        ArrayList<Integer> quantities = new ArrayList<>();

        // Process items
        if (!items.isEmpty() && !items.equalsIgnoreCase("None")) {
            String[] parts = items.split(", ");
            for (String part : parts) {
                String[] itemData = part.split("x ", 2);
                quantities.add(Integer.parseInt(itemData[0]));
                l1.add(itemData[1]);
            }
        }

        // Process prices & calculate total
        ArrayList<Integer> l2 = new ArrayList<>();
        int total = 0;
        if (!prices.isEmpty() && !prices.equals("0")) {
            String[] pArr = prices.split(" ");
            for (String p : pArr) l2.add(Integer.parseInt(p));

            for (int i = 0; i < l2.size() && i < quantities.size(); i++) {
                total += l2.get(i) * quantities.get(i);
            }
        }

        // Output
        if (l1.isEmpty()) {
            System.out.println("Order List: None");
            System.out.println("Total Price: 0 PHP");
        } else {
            System.out.println("Order List: " + String.join(", ", l1));
            System.out.println("Total Price: " + total + " PHP");
        }
        sc.close();
    }
}
